const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Saree Print Studio</title>\n  <style>\n    :root {\n      --bg: #ece9e2;\n      --panel: #f8f7f3;\n      --ink: #244f73;\n      --cloth: #ded4bd;\n      --text: #111315;\n      --muted: #6f6e68;\n      --line: rgba(17,19,21,.12);\n      --shadow: 0 28px 80px rgba(31,31,28,.18);\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n    }\n    * { box-sizing: border-box; }\n    html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }\n    body {\n      color: var(--text);\n      background:\n        radial-gradient(circle at 8% 18%, rgba(255,255,255,.86), transparent 30%),\n        radial-gradient(circle at 94% 8%, rgba(126,126,118,.18), transparent 28%),\n        linear-gradient(135deg, #d8d5cf, var(--bg));\n      user-select: none;\n    }\n    button, input { font: inherit; }\n    button {\n      border: 0;\n      cursor: pointer;\n      color: inherit;\n      background: transparent;\n    }\n    .app {\n      position: relative;\n      width: 100vw;\n      height: 100vh;\n      overflow: hidden;\n      isolation: isolate;\n    }\n    .texture {\n      position: absolute;\n      inset: -20px;\n      pointer-events: none;\n      opacity: .34;\n      background:\n        radial-gradient(circle at 12% 78%, transparent 0 26%, rgba(70,70,66,.18) 26.5% 27.5%, transparent 28%),\n        radial-gradient(circle at 92% 58%, transparent 0 21%, rgba(70,70,66,.14) 21.5% 22.5%, transparent 23%),\n        repeating-linear-gradient(18deg, rgba(32,32,30,.035) 0 1px, transparent 1px 8px);\n      mix-blend-mode: multiply;\n      z-index: 0;\n    }\n    .nav {\n      position: absolute;\n      left: clamp(18px, 4vw, 54px);\n      right: clamp(18px, 4vw, 54px);\n      top: 22px;\n      z-index: 20;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 18px;\n    }\n    .logo {\n      font-size: 18px;\n      font-weight: 900;\n      letter-spacing: -.02em;\n    }\n    .steps {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .step-pill {\n      min-width: 78px;\n      height: 32px;\n      border-radius: 999px;\n      border: 1px solid var(--line);\n      color: var(--muted);\n      background: rgba(255,255,255,.38);\n      font-size: 12px;\n      font-weight: 750;\n    }\n    .step-pill.active {\n      color: #fffaf0;\n      background: #111315;\n      border-color: #111315;\n    }\n    .screen {\n      position: absolute;\n      inset: 0;\n      display: none;\n      padding: 88px clamp(18px, 4vw, 54px) 34px;\n      z-index: 2;\n    }\n    .screen.active { display: block; }\n\n    .compose-layout {\n      height: 100%;\n      display: grid;\n      grid-template-columns: minmax(290px, 430px) minmax(420px, 680px);\n      gap: clamp(28px, 6vw, 82px);\n      align-items: center;\n      justify-content: center;\n    }\n    .eyebrow {\n      margin: 0 0 18px;\n      font-size: 12px;\n      font-weight: 850;\n      letter-spacing: .16em;\n      text-transform: uppercase;\n      color: var(--muted);\n    }\n    h1, h2 {\n      margin: 0;\n      font-family: Georgia, \"Times New Roman\", serif;\n      letter-spacing: 0;\n      font-weight: 500;\n    }\n    h1 {\n      max-width: 8ch;\n      font-size: clamp(54px, 8vw, 116px);\n      line-height: .88;\n    }\n    h2 {\n      max-width: 10ch;\n      font-size: clamp(46px, 6vw, 86px);\n      line-height: .9;\n    }\n    .lede {\n      max-width: 31rem;\n      margin: 22px 0 0;\n      color: var(--muted);\n      font-size: 17px;\n      line-height: 1.58;\n    }\n    .primary, .secondary {\n      min-height: 44px;\n      padding: 0 16px;\n      border-radius: 8px;\n      font-weight: 850;\n      transition: transform .18s ease, box-shadow .18s ease, background .18s ease;\n    }\n    .primary {\n      color: #fffaf0;\n      background: #111315;\n      box-shadow: 0 14px 30px rgba(17,19,21,.16);\n    }\n    .secondary {\n      border: 1px solid var(--line);\n      background: rgba(255,255,255,.48);\n    }\n    .primary:hover, .secondary:hover { transform: translateY(-1px); }\n    .studio-card {\n      border-radius: 18px;\n      background: rgba(248,247,243,.78);\n      border: 1px solid rgba(255,255,255,.86);\n      box-shadow: var(--shadow);\n      padding: clamp(16px, 2.5vw, 28px);\n      backdrop-filter: blur(16px);\n    }\n    .canvas-wrap {\n      border-radius: 16px;\n      padding: 14px;\n      background:\n        linear-gradient(135deg, rgba(255,255,255,.6), rgba(255,255,255,.18)),\n        #d8d0bc;\n      border: 1px solid rgba(72,60,43,.14);\n      box-shadow: inset 0 1px 0 rgba(255,255,255,.66);\n    }\n    #designCanvas {\n      display: block;\n      width: min(54vw, 560px);\n      height: min(54vw, 560px);\n      max-width: 560px;\n      max-height: 560px;\n      border-radius: 12px;\n      cursor: crosshair;\n      touch-action: none;\n      background:\n        repeating-linear-gradient(0deg, rgba(94,82,61,.13) 0 1px, transparent 1px 20px),\n        repeating-linear-gradient(90deg, rgba(94,82,61,.13) 0 1px, transparent 1px 20px),\n        #ded4bd;\n      box-shadow: inset 0 0 0 1px rgba(79,62,39,.18);\n    }\n    .controls-row {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      margin-top: 16px;\n    }\n    .brush {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      color: var(--muted);\n      font-size: 13px;\n      font-weight: 650;\n    }\n    .brush input { accent-color: #111315; }\n    .ornaments {\n      display: flex;\n      gap: 14px;\n      margin-top: 18px;\n      padding: 16px;\n      overflow-x: auto;\n      border-radius: 18px;\n      background:\n        linear-gradient(180deg, rgba(255,255,255,.08), rgba(0,0,0,.12)),\n        linear-gradient(105deg, #6b523d, #3f3024);\n      box-shadow: inset 0 -10px 22px rgba(0,0,0,.22), 0 18px 38px rgba(40,30,20,.14);\n    }\n    .ornament {\n      position: relative;\n      flex: 0 0 86px;\n      height: 74px;\n      border-radius: 15px;\n      border: 0;\n      background:\n        repeating-linear-gradient(92deg, rgba(255,255,255,.12) 0 3px, transparent 3px 16px),\n        linear-gradient(135deg, #a3693d, #754424 72%);\n      display: grid;\n      place-items: center;\n      box-shadow: inset 0 -11px 0 rgba(65,35,18,.38), 0 14px 16px rgba(43,27,15,.28);\n      transition: transform .18s ease, box-shadow .18s ease, outline .18s ease;\n    }\n    .ornament::after {\n      content: \"\";\n      position: absolute;\n      inset: auto 8px -9px 8px;\n      height: 14px;\n      border-radius: 0 0 12px 12px;\n      background: rgba(51,29,16,.52);\n      z-index: -1;\n    }\n    .ornament:hover, .ornament.selected {\n      transform: translateY(-4px) rotate(-1deg);\n      outline: 3px solid rgba(255,240,194,.8);\n      box-shadow: inset 0 -11px 0 rgba(65,35,18,.38), 0 20px 24px rgba(43,27,15,.32);\n    }\n    .ornament svg {\n      width: 42px;\n      height: 42px;\n      fill: #ffe9b5;\n      filter: drop-shadow(0 5px 0 rgba(73,38,16,.5)) drop-shadow(0 8px 6px rgba(0,0,0,.18));\n    }\n\n    .block-layout {\n      height: 100%;\n      display: grid;\n      grid-template-columns: minmax(300px, 420px) minmax(440px, 760px);\n      gap: clamp(30px, 5vw, 72px);\n      align-items: center;\n      justify-content: center;\n    }\n    .block-stage {\n      height: min(64vh, 620px);\n      min-height: 420px;\n      border-radius: 20px;\n      background:\n        radial-gradient(circle at 50% 6%, rgba(255,255,255,.9), transparent 35%),\n        linear-gradient(135deg, #f4f3ef, #d6d3cc);\n      border: 1px solid rgba(255,255,255,.78);\n      box-shadow: var(--shadow);\n      position: relative;\n      overflow: hidden;\n      perspective: 1000px;\n    }\n    #blockScene {\n      position: absolute;\n      inset: 0;\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n    .css-block {\n      position: absolute;\n      left: 50%;\n      top: 50%;\n      width: min(50vw, 420px);\n      height: min(50vw, 420px);\n      max-width: 420px;\n      max-height: 420px;\n      transform: translate(-50%, -50%) rotateX(58deg) rotateZ(-18deg);\n      transform-style: preserve-3d;\n      filter: drop-shadow(42px 58px 32px rgba(34,34,31,.24));\n    }\n    .css-block .slab-depth {\n      position: absolute;\n      inset: 22px -24px -34px 24px;\n      border-radius: 28px;\n      background: linear-gradient(135deg, #77736b, #33312d);\n    }\n    .css-block .slab-face {\n      position: absolute;\n      inset: 0;\n      border-radius: 28px;\n      background:\n        radial-gradient(circle at 18% 22%, rgba(255,255,255,.42) 0 1px, transparent 2px),\n        radial-gradient(circle at 72% 18%, rgba(60,58,54,.24) 0 2px, transparent 3px),\n        radial-gradient(circle at 52% 72%, rgba(45,43,40,.2) 0 2px, transparent 3px),\n        repeating-linear-gradient(17deg, rgba(255,255,255,.065) 0 1px, transparent 1px 11px),\n        linear-gradient(145deg, #d9d6cf, #a39e94 58%, #777168);\n      box-shadow:\n        inset 0 -28px 0 rgba(68,66,61,.25),\n        inset 0 0 0 11px rgba(240,238,231,.72),\n        inset 0 0 34px rgba(255,255,255,.22);\n    }\n    #blockRelief {\n      position: absolute;\n      inset: 76px;\n      width: calc(100% - 152px);\n      height: calc(100% - 152px);\n      z-index: 2;\n      filter: drop-shadow(0 18px 0 #817b70) drop-shadow(0 28px 14px rgba(0,0,0,.22));\n    }\n\n    .print-screen {\n      padding: 82px 28px 24px;\n      background:\n        radial-gradient(circle at 72% 4%, rgba(255,255,255,.96), transparent 30%),\n        radial-gradient(circle at 12% 86%, rgba(178,176,168,.22), transparent 32%),\n        linear-gradient(135deg, #f7f6f2, #e4e1da);\n    }\n    .print-table {\n      height: 100%;\n      position: relative;\n      display: grid;\n      place-items: center;\n      border-radius: 24px;\n      background:\n        linear-gradient(180deg, rgba(255,255,255,.7), rgba(255,255,255,.3)),\n        repeating-linear-gradient(90deg, rgba(30,30,28,.028) 0 1px, transparent 1px 32px);\n      box-shadow: inset 0 0 0 1px rgba(17,19,21,.08), 0 28px 80px rgba(31,31,28,.12);\n    }\n    .fabric-frame {\n      position: relative;\n      width: min(82vw, 1160px);\n      height: min(68vh, 690px);\n      transform: none;\n      filter: drop-shadow(0 24px 34px rgba(31,31,28,.16));\n    }\n    #fabricCanvas {\n      position: absolute;\n      inset: 0;\n      width: 100%;\n      height: 100%;\n      border-radius: 14px;\n      cursor: none;\n      touch-action: none;\n      box-shadow: inset 0 0 0 1px rgba(78,54,35,.2), inset 0 22px 34px rgba(255,255,255,.26), inset 0 -30px 48px rgba(50,36,24,.17);\n    }\n    .paint-pad {\n      position: absolute;\n      right: clamp(20px, 5vw, 74px);\n      bottom: clamp(30px, 8vh, 76px);\n      width: 180px;\n      height: 118px;\n      border-radius: 20px;\n      transform: perspective(650px) rotateX(55deg) rotateZ(-6deg);\n      background:\n        repeating-linear-gradient(90deg, rgba(255,255,255,.18) 0 8px, rgba(0,0,0,.05) 8px 16px),\n        radial-gradient(ellipse at 40% 34%, rgba(255,255,255,.35), transparent 16%),\n        linear-gradient(135deg, rgba(255,255,255,.12), rgba(0,0,0,.2)),\n        var(--ink);\n      box-shadow: inset 0 0 0 13px rgba(255,255,255,.5), inset 0 0 0 25px rgba(0,0,0,.06), 0 24px 34px rgba(31,31,28,.22);\n    }\n    .floating-block {\n      position: absolute;\n      width: 138px;\n      height: 138px;\n      pointer-events: none;\n      transform: translate(-50%, -50%) scale(var(--scale, 1));\n      z-index: 8;\n      filter: drop-shadow(0 var(--sy, 26px) var(--blur, 18px) rgba(20,12,6,.36));\n    }\n    .floating-block.hit { animation: hit .3s cubic-bezier(.2,.9,.2,1); }\n    @keyframes hit {\n      0% { transform: translate(-50%, -72%) scale(1.02); filter: drop-shadow(0 34px 22px rgba(20,12,6,.28)); }\n      44% { transform: translate(-50%, -50%) scale(.92); filter: drop-shadow(0 5px 5px rgba(20,12,6,.36)); }\n      100% { transform: translate(-50%, -50%) scale(1); }\n    }\n    .floating-block .mini-depth {\n      position: absolute;\n      inset: 8px 0 -12px 0;\n      border-radius: 18px;\n      background: linear-gradient(135deg, #827c72, #373431);\n      opacity: .45;\n    }\n    .floating-block .mini-face {\n      position: absolute;\n      inset: 0;\n      border-radius: 16px;\n      background:\n        radial-gradient(circle at 18% 22%, rgba(255,255,255,.45) 0 1px, transparent 2px),\n        radial-gradient(circle at 78% 24%, rgba(45,43,40,.2) 0 2px, transparent 3px),\n        repeating-linear-gradient(18deg, rgba(255,255,255,.065) 0 1px, transparent 1px 10px),\n        linear-gradient(145deg, #d8d5cd, #a9a399 56%, #7f786e);\n      box-shadow: inset 0 -16px 0 rgba(74,71,66,.25), inset 0 0 0 8px rgba(235,233,226,.66);\n    }\n    #printBlockRelief {\n      position: absolute;\n      inset: 28px;\n      width: 82px;\n      height: 82px;\n      z-index: 2;\n      filter: drop-shadow(0 8px 0 #858075) drop-shadow(0 13px 8px rgba(0,0,0,.24));\n    }\n    .print-ui {\n      position: absolute;\n      left: 24px;\n      bottom: 24px;\n      right: 24px;\n      display: flex;\n      align-items: end;\n      justify-content: space-between;\n      gap: 16px;\n      pointer-events: none;\n      z-index: 10;\n    }\n    .print-ui > * { pointer-events: auto; }\n    .print-panel {\n      border-radius: 10px;\n      padding: 14px;\n      color: #171716;\n      background: rgba(255,255,255,.74);\n      border: 1px solid rgba(17,19,21,.1);\n      box-shadow: 0 18px 38px rgba(31,31,28,.13);\n      backdrop-filter: blur(10px);\n    }\n    .dyes, .fabric-swatches {\n      display: flex;\n      gap: 9px;\n      margin-top: 10px;\n    }\n    .dye, .fabric-swatch {\n      width: 34px;\n      height: 34px;\n      border-radius: 50%;\n      background: var(--c);\n      border: 2px solid rgba(255,255,255,.9);\n      box-shadow: inset 0 -8px 10px rgba(0,0,0,.18), 0 6px 16px rgba(31,31,28,.16);\n    }\n    .dye.active, .fabric-swatch.active { outline: 3px solid #111315; outline-offset: 3px; }\n    .meter {\n      width: 150px;\n      height: 12px;\n      border-radius: 999px;\n      overflow: hidden;\n      background: rgba(255,255,255,.22);\n      margin-top: 10px;\n    }\n    .meter i {\n      display: block;\n      height: 100%;\n      width: 0;\n      background: var(--ink);\n      transition: width .2s ease;\n    }\n    .toast {\n      position: absolute;\n      left: 50%;\n      top: 86px;\n      transform: translateX(-50%);\n      z-index: 11;\n      padding: 10px 14px;\n      border-radius: 8px;\n      color: #fff2d8;\n      background: rgba(17,19,21,.78);\n      border: 1px solid rgba(255,255,255,.13);\n      box-shadow: 0 16px 38px rgba(31,31,28,.18);\n      backdrop-filter: blur(8px);\n      font-size: 13px;\n    }\n    .reveal {\n      position: absolute;\n      inset: 0;\n      z-index: 40;\n      display: none;\n      grid-template-columns: 1fr 320px;\n      gap: 24px;\n      padding: 28px;\n      background: linear-gradient(135deg, rgba(31,30,28,.94), rgba(82,69,52,.94));\n    }\n    .reveal.active { display: grid; }\n    .reveal-scroll {\n      display: grid;\n      place-items: center;\n      overflow: auto;\n    }\n    #finalCanvas {\n      width: min(72vw, 1020px);\n      border-radius: 12px;\n      box-shadow: 0 36px 90px rgba(0,0,0,.42);\n    }\n    .record {\n      align-self: center;\n      color: #fff0d3;\n    }\n    .record h2 { font-size: 44px; }\n    .record p { color: rgba(255,240,211,.8); line-height: 1.5; }\n    .stat {\n      border-top: 1px solid rgba(255,255,255,.16);\n      display: flex;\n      justify-content: space-between;\n      padding: 12px 0;\n    }\n    @media (max-width: 900px) {\n      html, body { overflow: auto; }\n      .app { min-height: 100vh; height: auto; overflow: visible; }\n      .nav { position: fixed; }\n      .screen { position: relative; min-height: 100vh; }\n      .compose-layout, .block-layout { grid-template-columns: 1fr; align-items: start; }\n      #designCanvas { width: calc(100vw - 80px); height: calc(100vw - 80px); }\n      .ornaments { grid-template-columns: repeat(3, 1fr); }\n      .fabric-frame { width: 94vw; height: 58vh; }\n      .paint-pad { width: 130px; height: 88px; right: 14px; bottom: 128px; }\n      .print-ui { flex-direction: column; align-items: stretch; }\n      .reveal { grid-template-columns: 1fr; }\n      #finalCanvas { width: 92vw; }\n    }\n  </style>\n</head>\n<body>\n  <main class=\"app\">\n    <div class=\"texture\"></div>\n    <nav class=\"nav\">\n      <div class=\"logo\">Saree Print Studio</div>\n      <div class=\"steps\" aria-label=\"Workflow\">\n        <button class=\"step-pill active\" data-step=\"compose\">Compose</button>\n        <button class=\"step-pill\" data-step=\"carve\">Carve</button>\n        <button class=\"step-pill\" data-step=\"print\">Print</button>\n      </div>\n    </nav>\n\n    <section class=\"screen active\" id=\"composeScreen\">\n      <div class=\"compose-layout\">\n        <div>\n          <p class=\"eyebrow\">Step 01 / Motif</p>\n          <h1>Design your block</h1>\n          <p class=\"lede\">Draw directly on the canvas, or pick up the small ornament blocks from the tray and drop them into your design. The black shape becomes the raised surface of your printing block.</p>\n        </div>\n        <div class=\"studio-card\">\n          <div class=\"canvas-wrap\">\n            <canvas id=\"designCanvas\" width=\"560\" height=\"560\" aria-label=\"Motif drawing canvas\"></canvas>\n          </div>\n          <div class=\"ornaments\" id=\"ornaments\" aria-label=\"Ornament tray\"></div>\n          <div class=\"controls-row\">\n            <label class=\"brush\">Brush <input id=\"brush\" type=\"range\" min=\"6\" max=\"52\" value=\"20\"></label>\n            <div>\n              <button class=\"secondary\" id=\"eraseBtn\">Erase</button>\n              <button class=\"secondary\" id=\"clearBtn\">Clear</button>\n              <button class=\"primary\" id=\"toCarve\">Make block</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"screen\" id=\"carveScreen\">\n      <div class=\"block-layout\">\n        <div>\n          <p class=\"eyebrow\">Step 02 / Block</p>\n          <h2>Your motif becomes a raised surface</h2>\n          <p class=\"lede\">The drawing is converted into a relief on a heavy stone-like block. Rotate your pointer across the scene, then continue when it feels ready to print.</p>\n          <p class=\"lede\" style=\"font-size:14px\">The live print tool uses this exact mask, including the edges from your drawing and placed ornaments.</p>\n          <div class=\"controls-row\" style=\"justify-content:flex-start\">\n            <button class=\"secondary\" id=\"backCompose\">Back to canvas</button>\n            <button class=\"primary\" id=\"toPrint\">Start printing</button>\n          </div>\n        </div>\n        <div class=\"block-stage\" id=\"blockStage\">\n          <canvas id=\"blockScene\"></canvas>\n          <div class=\"css-block\" id=\"cssBlock\">\n            <div class=\"slab-depth\"></div>\n            <div class=\"slab-face\"></div>\n            <canvas id=\"blockRelief\" width=\"260\" height=\"260\"></canvas>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"screen print-screen\" id=\"printScreen\">\n      <div class=\"print-table\">\n        <div class=\"toast\" id=\"toast\">Dip the block into the paint pad, then press it onto the fabric.</div>\n        <div class=\"fabric-frame\">\n          <canvas id=\"fabricCanvas\" width=\"1800\" height=\"1000\"></canvas>\n        </div>\n        <div class=\"paint-pad\" id=\"paintPad\" title=\"Paint pad\"></div>\n        <div class=\"floating-block\" id=\"printBlock\">\n          <div class=\"mini-depth\"></div>\n          <div class=\"mini-face\"></div>\n          <canvas id=\"printBlockRelief\" width=\"160\" height=\"160\"></canvas>\n        </div>\n        <div class=\"print-ui\">\n          <div class=\"print-panel\">\n            <strong>Paint colors</strong>\n            <div class=\"dyes\" id=\"dyes\"></div>\n          </div>\n          <div class=\"print-panel\">\n            <strong>Fabric colors</strong>\n            <div class=\"fabric-swatches\" id=\"fabricSwatches\"></div>\n          </div>\n          <div class=\"print-panel\">\n            <strong>Ink on block</strong>\n            <div class=\"meter\"><i id=\"inkMeter\"></i></div>\n          </div>\n          <div>\n            <button class=\"secondary\" id=\"moveFabric\">Move fabric</button>\n            <button class=\"primary\" id=\"finish\">Reveal saree</button>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"reveal\" id=\"reveal\">\n      <div class=\"reveal-scroll\"><canvas id=\"finalCanvas\" width=\"1400\" height=\"4200\"></canvas></div>\n      <aside class=\"record\">\n        <p class=\"eyebrow\" style=\"color:rgba(255,240,211,.64)\">Finished textile</p>\n        <h2>Made by hand</h2>\n        <p>Every impression keeps its own pressure, fading, angle, and pigment variation.</p>\n        <div class=\"stat\"><span>Impressions</span><strong id=\"statPrints\">0</strong></div>\n        <div class=\"stat\"><span>Times inked</span><strong id=\"statInks\">0</strong></div>\n        <div class=\"stat\"><span>Colors used</span><strong id=\"statColors\">1</strong></div>\n        <button class=\"primary\" id=\"exportBtn\" style=\"width:100%;margin-top:16px\">Export PNG</button>\n        <button class=\"secondary\" id=\"againBtn\" style=\"width:100%;margin-top:10px;color:#fff0d3\">Start again</button>\n      </aside>\n    </section>\n  </main>\n\n  <script>\n    const designCanvas = document.getElementById(\"designCanvas\");\n    const dtx = designCanvas.getContext(\"2d\");\n    const blockRelief = document.getElementById(\"blockRelief\");\n    const brx = blockRelief.getContext(\"2d\");\n    const printRelief = document.getElementById(\"printBlockRelief\");\n    const prx = printRelief.getContext(\"2d\");\n    const fabricCanvas = document.getElementById(\"fabricCanvas\");\n    const fcx = fabricCanvas.getContext(\"2d\");\n    const finalCanvas = document.getElementById(\"finalCanvas\");\n    const finalCx = finalCanvas.getContext(\"2d\");\n    const motifMask = document.createElement(\"canvas\");\n    motifMask.width = motifMask.height = 280;\n    const mtx = motifMask.getContext(\"2d\");\n\n    const state = {\n      step: \"compose\",\n      drawMode: \"draw\",\n      selected: \"flower\",\n      ink: 0,\n      inks: 0,\n      color: \"#244f73\",\n      fabricColor: \"#ded4bd\",\n      colors: new Set([\"#244f73\"]),\n      stamps: [],\n      segment: 0,\n      segments: 6,\n      pointer: { x: 900, y: 500, sx: innerWidth * .5, sy: innerHeight * .5, inside: false }\n    };\n\n    const ornamentDefs = [\n      [\"flower\", '<svg viewBox=\"0 0 100 100\"><path d=\"M50 7c8 20 16 26 37 22-14 17-14 28 0 42-21-4-29 3-37 22-8-19-16-26-37-22 14-14 14-25 0-42 21 4 29-2 37-22Z\"/></svg>'],\n      [\"leaf\", '<svg viewBox=\"0 0 100 100\"><path d=\"M15 72C20 32 50 13 86 17 78 58 51 82 15 72Z\"/></svg>'],\n      [\"petal\", '<svg viewBox=\"0 0 100 100\"><path d=\"M50 6c31 28 31 60 0 88-31-28-31-60 0-88Z\"/></svg>'],\n      [\"diamond\", '<svg viewBox=\"0 0 100 100\"><path d=\"M50 6 94 50 50 94 6 50Z\"/></svg>'],\n      [\"ring\", '<svg viewBox=\"0 0 100 100\"><path d=\"M50 10a40 40 0 1 0 0 80 40 40 0 0 0 0-80Zm0 23a17 17 0 1 1 0 34 17 17 0 0 1 0-34Z\"/></svg>'],\n      [\"border\", '<svg viewBox=\"0 0 100 100\"><path d=\"M12 60c25-43 51-43 76 0-27-17-49-15-76 0Z\"/><circle cx=\"30\" cy=\"35\" r=\"10\"/><circle cx=\"70\" cy=\"35\" r=\"10\"/></svg>']\n    ];\n    const colors = [[\"Indigo\", \"#244f73\"], [\"Red\", \"#a73a32\"], [\"Gold\", \"#c8942c\"], [\"Black\", \"#1b1917\"], [\"Green\", \"#315d43\"], [\"Clay\", \"#a85d35\"]];\n    const fabricColors = [[\"Ivory\", \"#ded4bd\"], [\"White\", \"#f3efe5\"], [\"Blush\", \"#ead2c7\"], [\"Sage\", \"#c9d1bf\"], [\"Mustard\", \"#d6bb69\"], [\"Indigo\", \"#aeb9c7\"]];\n\n    function setStep(step) {\n      state.step = step;\n      document.querySelectorAll(\".screen\").forEach(el => el.classList.remove(\"active\"));\n      document.getElementById(step + \"Screen\")?.classList.add(\"active\");\n      document.querySelectorAll(\".step-pill\").forEach(el => el.classList.toggle(\"active\", el.dataset.step === step));\n      if (step === \"carve\") {\n        updateMotifMask();\n        drawReliefs();\n        window.dispatchEvent(new CustomEvent(\"motif-ready\", { detail: { url: motifMask.toDataURL(\"image/png\") } }));\n      }\n      if (step === \"print\") {\n        updateMotifMask();\n        drawReliefs();\n        renderFabric();\n        movePrintBlock(state.pointer.sx, state.pointer.sy);\n      }\n    }\n\n    function drawCanvasBase() {\n      dtx.clearRect(0, 0, designCanvas.width, designCanvas.height);\n      dtx.save();\n      dtx.fillStyle = \"#111315\";\n      dtx.translate(280, 280);\n      dtx.scale(1.35, 1.35);\n      shapePath(dtx, \"flower\");\n      dtx.fill();\n      dtx.restore();\n    }\n\n    function shapePath(c, type) {\n      c.beginPath();\n      if (type === \"flower\") {\n        c.moveTo(0, -66); c.bezierCurveTo(34, -42, 30, -12, 78, 0); c.bezierCurveTo(36, 18, 28, 38, 0, 66); c.bezierCurveTo(-28, 38, -36, 18, -78, 0); c.bezierCurveTo(-30, -12, -34, -42, 0, -66);\n      } else if (type === \"leaf\") {\n        c.moveTo(-70, 36); c.bezierCurveTo(-54, -48, 18, -74, 72, -48); c.bezierCurveTo(56, 24, 8, 58, -70, 36);\n      } else if (type === \"petal\") {\n        c.moveTo(0, -72); c.bezierCurveTo(44, -30, 38, 40, 0, 72); c.bezierCurveTo(-38, 40, -44, -30, 0, -72);\n      } else if (type === \"diamond\") {\n        c.moveTo(0, -70); c.lineTo(70, 0); c.lineTo(0, 70); c.lineTo(-70, 0); c.closePath();\n      } else if (type === \"ring\") {\n        c.arc(0, 0, 62, 0, Math.PI * 2); c.arc(0, 0, 32, 0, Math.PI * 2, true);\n      } else {\n        c.moveTo(-78, 14); c.bezierCurveTo(-34, -62, 34, -62, 78, 14); c.bezierCurveTo(35, -12, -35, -12, -78, 14);\n      }\n    }\n\n    function placeOrnament(type, x, y, scale = 1) {\n      dtx.save();\n      dtx.translate(x, y);\n      dtx.rotate((Math.random() - .5) * .45);\n      dtx.scale(scale, scale);\n      dtx.fillStyle = \"#111315\";\n      shapePath(dtx, type);\n      dtx.fill();\n      dtx.restore();\n    }\n\n    function updateMotifMask() {\n      mtx.clearRect(0, 0, 280, 280);\n      mtx.drawImage(designCanvas, 0, 0, 280, 280);\n      const img = mtx.getImageData(0, 0, 280, 280);\n      const data = img.data;\n      for (let i = 0; i < data.length; i += 4) {\n        const dark = 255 - (data[i] + data[i + 1] + data[i + 2]) / 3;\n        data[i] = data[i + 1] = data[i + 2] = 0;\n        data[i + 3] = data[i + 3] > 20 && dark > 35 ? 255 : 0;\n      }\n      mtx.putImageData(img, 0, 0);\n    }\n\n    function tintedMotif(color, size = 280) {\n      const c = document.createElement(\"canvas\");\n      c.width = c.height = size;\n      const x = c.getContext(\"2d\");\n      x.drawImage(motifMask, 0, 0, size, size);\n      x.globalCompositeOperation = \"source-in\";\n      x.fillStyle = color;\n      x.fillRect(0, 0, size, size);\n      return c;\n    }\n\n    function drawReliefs() {\n      [brx, prx].forEach((x, index) => {\n        const s = index ? 160 : 260;\n        x.clearRect(0, 0, s, s);\n        x.save();\n        x.shadowColor = \"rgba(54,50,44,.38)\";\n        x.shadowBlur = index ? 7 : 14;\n        x.shadowOffsetY = index ? 9 : 18;\n        x.drawImage(tintedMotif(state.ink > .04 ? state.color : \"#d8c17d\", s), 0, 0);\n        x.restore();\n      });\n    }\n\n    function seedRand(seed) {\n      let t = seed + 0x6D2B79F5;\n      return () => {\n        t = Math.imul(t ^ t >>> 15, t | 1);\n        t ^= t + Math.imul(t ^ t >>> 7, t | 61);\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    function drawFabricBase(c, w, h) {\n      c.clearRect(0, 0, w, h);\n      c.fillStyle = \"var(--cloth)\";\n      c.fillStyle = state.fabricColor;\n      c.fillRect(0, 0, w, h);\n      const shade = c.createLinearGradient(0, 0, w, h);\n      shade.addColorStop(0, \"rgba(255,255,255,.28)\");\n      shade.addColorStop(.7, \"rgba(95,78,56,.08)\");\n      shade.addColorStop(1, \"rgba(48,39,28,.18)\");\n      c.fillStyle = shade;\n      c.fillRect(0, 0, w, h);\n      c.save();\n      for (let x = -20; x < w + 20; x += 9) {\n        c.strokeStyle = x % 45 === 0 ? \"rgba(82,72,57,.28)\" : \"rgba(116,105,86,.12)\";\n        c.beginPath();\n        c.moveTo(x + Math.sin((x + state.segment * 31) * .035) * 4, 0);\n        c.bezierCurveTo(x + 10, h * .32, x - 7, h * .66, x + 12, h);\n        c.stroke();\n      }\n      for (let y = -20; y < h + 20; y += 7) {\n        c.strokeStyle = y % 42 === 0 ? \"rgba(76,67,53,.18)\" : \"rgba(255,255,255,.12)\";\n        c.beginPath();\n        c.moveTo(0, y + Math.sin((y + state.segment * 19) * .045) * 3);\n        c.bezierCurveTo(w * .32, y - 5, w * .66, y + 6, w, y + Math.cos(y * .025) * 4);\n        c.stroke();\n      }\n      c.restore();\n      c.save();\n      c.globalCompositeOperation = \"multiply\";\n      for (let i = 0; i < 7; i++) {\n        const y = h * (.12 + i * .13) + Math.sin(i + state.segment) * 18;\n        const fold = c.createLinearGradient(0, y - 38, 0, y + 52);\n        fold.addColorStop(0, \"rgba(255,255,255,0)\");\n        fold.addColorStop(.5, \"rgba(90,72,50,.055)\");\n        fold.addColorStop(1, \"rgba(255,255,255,0)\");\n        c.fillStyle = fold;\n        c.fillRect(0, y - 42, w, 96);\n      }\n      c.restore();\n    }\n\n    function makeStamp(stamp) {\n      const temp = document.createElement(\"canvas\");\n      temp.width = temp.height = 300;\n      const x = temp.getContext(\"2d\");\n      x.translate(150, 150);\n      x.rotate(stamp.r);\n      x.scale(stamp.scale, stamp.scale);\n      x.translate(-140, -140);\n      x.drawImage(motifMask, 0, 0, 280, 280);\n      const img = x.getImageData(0, 0, 300, 300);\n      const data = img.data;\n      const rr = seedRand(stamp.seed);\n      for (let y = 0; y < 300; y++) for (let xx = 0; xx < 300; xx++) {\n        const i = (y * 300 + xx) * 4;\n        if (!data[i + 3]) continue;\n        const stripe = (xx + stamp.seed) % 19 < 3 ? .56 : 1;\n        const dry = rr() < .0025 + (1 - stamp.ink) * .011 ? 0 : 1;\n        const n = .76 + Math.sin(xx * .08 + stamp.seed) * .18 + Math.cos(y * .063) * .12;\n        data[i] = parseInt(stamp.color.slice(1,3), 16);\n        data[i + 1] = parseInt(stamp.color.slice(3,5), 16);\n        data[i + 2] = parseInt(stamp.color.slice(5,7), 16);\n        data[i + 3] = Math.max(0, Math.min(225, 255 * stamp.opacity * n * stripe * dry));\n      }\n      x.putImageData(img, 0, 0);\n      return temp;\n    }\n\n    function drawStamp(c, stamp, factor = 1) {\n      const img = makeStamp(stamp);\n      c.save();\n      c.globalCompositeOperation = \"multiply\";\n      c.filter = `blur(${stamp.blur * factor}px)`;\n      c.drawImage(img, stamp.x * factor - img.width * factor / 2, stamp.y * factor - img.height * factor / 2, img.width * factor, img.height * factor);\n      c.restore();\n    }\n\n    function renderFabric() {\n      drawFabricBase(fcx, fabricCanvas.width, fabricCanvas.height);\n      const start = state.segment * fabricCanvas.width;\n      const end = start + fabricCanvas.width;\n      state.stamps.filter(s => s.gx >= start && s.gx <= end).forEach(s => drawStamp(fcx, { ...s, x: s.gx - start }));\n      updateUi();\n    }\n\n    function updateUi() {\n      document.documentElement.style.setProperty(\"--ink\", state.color);\n      document.documentElement.style.setProperty(\"--cloth\", state.fabricColor);\n      document.getElementById(\"inkMeter\").style.width = `${Math.round(state.ink * 100)}%`;\n      drawReliefs();\n    }\n\n    function canvasPoint(canvas, e) {\n      const rect = canvas.getBoundingClientRect();\n      return { x: (e.clientX - rect.left) / rect.width * canvas.width, y: (e.clientY - rect.top) / rect.height * canvas.height };\n    }\n\n    let drawing = false, last = null;\n    function drawLine(p) {\n      dtx.save();\n      dtx.lineCap = \"round\";\n      dtx.lineJoin = \"round\";\n      dtx.lineWidth = Number(document.getElementById(\"brush\").value);\n      if (state.drawMode === \"erase\") {\n        dtx.globalCompositeOperation = \"destination-out\";\n        dtx.strokeStyle = \"#000\";\n      } else {\n        dtx.globalCompositeOperation = \"source-over\";\n        dtx.strokeStyle = \"#111315\";\n      }\n      dtx.beginPath();\n      dtx.moveTo(last ? last.x : p.x, last ? last.y : p.y);\n      dtx.lineTo(p.x, p.y);\n      dtx.stroke();\n      dtx.restore();\n      last = p;\n    }\n\n    designCanvas.addEventListener(\"pointerdown\", e => {\n      drawing = true;\n      designCanvas.setPointerCapture(e.pointerId);\n      last = canvasPoint(designCanvas, e);\n      drawLine(last);\n    });\n    designCanvas.addEventListener(\"pointermove\", e => { if (drawing) drawLine(canvasPoint(designCanvas, e)); });\n    designCanvas.addEventListener(\"pointerup\", () => { drawing = false; last = null; });\n    designCanvas.addEventListener(\"pointercancel\", () => { drawing = false; last = null; });\n    designCanvas.addEventListener(\"dragover\", e => e.preventDefault());\n    designCanvas.addEventListener(\"drop\", e => {\n      e.preventDefault();\n      const type = e.dataTransfer.getData(\"text/plain\") || state.selected;\n      const p = canvasPoint(designCanvas, e);\n      placeOrnament(type, p.x, p.y, .85);\n    });\n    designCanvas.addEventListener(\"click\", e => {\n      if (state.drawMode === \"place\") {\n        const p = canvasPoint(designCanvas, e);\n        placeOrnament(state.selected, p.x, p.y, .85);\n      }\n    });\n\n    ornamentDefs.forEach(([type, svg], i) => {\n      const b = document.createElement(\"button\");\n      b.className = \"ornament\" + (i === 0 ? \" selected\" : \"\");\n      b.draggable = true;\n      b.title = type;\n      b.innerHTML = svg;\n      b.addEventListener(\"dragstart\", e => e.dataTransfer.setData(\"text/plain\", type));\n      b.addEventListener(\"click\", () => {\n        state.selected = type;\n        state.drawMode = \"place\";\n        document.querySelectorAll(\".ornament\").forEach(el => el.classList.toggle(\"selected\", el === b));\n      });\n      document.getElementById(\"ornaments\").appendChild(b);\n    });\n\n    document.getElementById(\"eraseBtn\").onclick = () => {\n      state.drawMode = state.drawMode === \"erase\" ? \"draw\" : \"erase\";\n      document.getElementById(\"eraseBtn\").textContent = state.drawMode === \"erase\" ? \"Draw\" : \"Erase\";\n    };\n    document.getElementById(\"clearBtn\").onclick = () => dtx.clearRect(0, 0, designCanvas.width, designCanvas.height);\n    document.getElementById(\"toCarve\").onclick = () => setStep(\"carve\");\n    document.getElementById(\"backCompose\").onclick = () => setStep(\"compose\");\n    document.getElementById(\"toPrint\").onclick = () => setStep(\"print\");\n\n    function fabricPoint(e) {\n      const rect = fabricCanvas.getBoundingClientRect();\n      const x = (e.clientX - rect.left) / rect.width * fabricCanvas.width;\n      const y = (e.clientY - rect.top) / rect.height * fabricCanvas.height;\n      return { x, y, inside: x >= 0 && y >= 0 && x <= fabricCanvas.width && y <= fabricCanvas.height };\n    }\n    function movePrintBlock(sx, sy) {\n      const b = document.getElementById(\"printBlock\");\n      b.style.left = `${sx}px`;\n      b.style.top = `${sy}px`;\n      b.style.setProperty(\"--scale\", 1 + state.ink * .025);\n      b.style.setProperty(\"--sy\", `${28 + state.ink * 12}px`);\n      b.style.setProperty(\"--blur\", `${16 + state.ink * 8}px`);\n    }\n    document.addEventListener(\"pointermove\", e => {\n      if (state.step !== \"print\") return;\n      const p = fabricPoint(e);\n      state.pointer = { ...p, sx: e.clientX, sy: e.clientY };\n      movePrintBlock(e.clientX, e.clientY);\n    });\n    document.addEventListener(\"pointerdown\", e => {\n      if (state.step !== \"print\") return;\n      const pad = document.getElementById(\"paintPad\").getBoundingClientRect();\n      if (e.clientX >= pad.left && e.clientX <= pad.right && e.clientY >= pad.top && e.clientY <= pad.bottom) {\n        state.ink = 1;\n        state.inks += 1;\n        document.getElementById(\"toast\").textContent = \"The block is loaded with paint. Press it onto the fabric.\";\n        updateUi();\n        return;\n      }\n      const p = fabricPoint(e);\n      if (!p.inside) return;\n      if (state.ink < .08) {\n        document.getElementById(\"toast\").textContent = \"The print has faded. Dip the block again.\";\n        return;\n      }\n      const seed = Math.floor(Math.random() * 9999999);\n      const rr = seedRand(seed);\n      state.stamps.push({\n        gx: state.segment * fabricCanvas.width + p.x + (rr() - .5) * 14,\n        x: p.x,\n        y: p.y + (rr() - .5) * 14,\n        r: (rr() - .5) * .025,\n        scale: .54 + rr() * .08,\n        color: state.color,\n        opacity: .34 + state.ink * .5 + rr() * .08,\n        ink: state.ink,\n        blur: .25 + rr() * 1.2,\n        seed\n      });\n      state.ink = Math.max(0, state.ink - (.17 + rr() * .12));\n      const b = document.getElementById(\"printBlock\");\n      b.classList.remove(\"hit\");\n      void b.offsetWidth;\n      b.classList.add(\"hit\");\n      document.getElementById(\"toast\").textContent = state.ink > .14 ? \"Lift, move, and press again.\" : \"The pigment is fading. Return to the paint pad.\";\n      renderFabric();\n    });\n\n    colors.forEach(([name, color], i) => {\n      const b = document.createElement(\"button\");\n      b.className = \"dye\" + (i === 0 ? \" active\" : \"\");\n      b.style.setProperty(\"--c\", color);\n      b.title = name;\n      b.onclick = () => {\n        state.color = color;\n        state.colors.add(color);\n        document.querySelectorAll(\".dye\").forEach(el => el.classList.toggle(\"active\", el === b));\n        updateUi();\n      };\n      document.getElementById(\"dyes\").appendChild(b);\n    });\n    fabricColors.forEach(([name, color], i) => {\n      const b = document.createElement(\"button\");\n      b.className = \"fabric-swatch\" + (i === 0 ? \" active\" : \"\");\n      b.style.setProperty(\"--c\", color);\n      b.title = name;\n      b.onclick = () => {\n        state.fabricColor = color;\n        document.querySelectorAll(\".fabric-swatch\").forEach(el => el.classList.toggle(\"active\", el === b));\n        renderFabric();\n      };\n      document.getElementById(\"fabricSwatches\").appendChild(b);\n    });\n    document.getElementById(\"moveFabric\").onclick = () => {\n      state.segment = Math.min(state.segments - 1, state.segment + 1);\n      renderFabric();\n      document.getElementById(\"toast\").textContent = state.segment === state.segments - 1 ? \"This is the final section. Make it denser if you like.\" : \"A fresh length of fabric moved onto the table.\";\n    };\n    document.getElementById(\"finish\").onclick = () => {\n      drawFabricBase(finalCx, finalCanvas.width, finalCanvas.height);\n      const segH = finalCanvas.height / state.segments;\n      state.stamps.forEach(s => {\n        const seg = Math.floor(s.gx / fabricCanvas.width);\n        const localX = s.gx - seg * fabricCanvas.width;\n        drawStamp(finalCx, { ...s, x: localX / fabricCanvas.width * finalCanvas.width, y: seg * segH + s.y / fabricCanvas.height * segH, scale: s.scale * .55 });\n      });\n      document.getElementById(\"statPrints\").textContent = state.stamps.length;\n      document.getElementById(\"statInks\").textContent = state.inks;\n      document.getElementById(\"statColors\").textContent = state.colors.size;\n      document.getElementById(\"reveal\").classList.add(\"active\");\n    };\n    document.getElementById(\"againBtn\").onclick = () => location.reload();\n    document.getElementById(\"exportBtn\").onclick = () => {\n      const a = document.createElement(\"a\");\n      a.download = \"saree-print.png\";\n      a.href = finalCanvas.toDataURL(\"image/png\");\n      a.click();\n    };\n\n    document.querySelectorAll(\".step-pill\").forEach(btn => {\n      btn.onclick = () => {\n        if (btn.dataset.step === \"compose\") setStep(\"compose\");\n        if (btn.dataset.step === \"carve\") setStep(\"carve\");\n        if (btn.dataset.step === \"print\") setStep(\"print\");\n      };\n    });\n    document.getElementById(\"blockStage\").addEventListener(\"pointermove\", e => {\n      const rect = e.currentTarget.getBoundingClientRect();\n      const x = (e.clientX - rect.left) / rect.width - .5;\n      const y = (e.clientY - rect.top) / rect.height - .5;\n      document.getElementById(\"cssBlock\").style.transform = `translate(-50%, -50%) rotateX(${58 - y * 8}deg) rotateZ(${-18 + x * 8}deg)`;\n    });\n\n    drawCanvasBase();\n    updateMotifMask();\n    drawReliefs();\n    renderFabric();\n  </script>\n\n  <script type=\"module\">\n    const sceneCanvas = document.getElementById(\"blockScene\");\n    let THREE;\n    try {\n      THREE = await import(\"https://unpkg.com/three@0.160.0/build/three.module.js\");\n    } catch (error) {\n      sceneCanvas.style.display = \"none\";\n    }\n    if (THREE) {\n      const renderer = new THREE.WebGLRenderer({ canvas: sceneCanvas, alpha: true, antialias: true });\n      renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));\n      renderer.shadowMap.enabled = true;\n      const scene = new THREE.Scene();\n      const camera = new THREE.PerspectiveCamera(32, 1, .1, 60);\n      camera.position.set(0, 4.8, 8.4);\n      camera.lookAt(0, 0, 0);\n      scene.add(new THREE.HemisphereLight(0xffffff, 0x9b9487, 1.8));\n      const key = new THREE.DirectionalLight(0xffffff, 3);\n      key.position.set(-4, 7, 6);\n      key.castShadow = true;\n      scene.add(key);\n      const floor = new THREE.Mesh(new THREE.PlaneGeometry(10, 7), new THREE.MeshStandardMaterial({ color: 0xf4f3ef, roughness: .86 }));\n      floor.rotation.x = -Math.PI / 2;\n      floor.position.y = -1.18;\n      floor.receiveShadow = true;\n      scene.add(floor);\n\n      function texture() {\n        const c = document.createElement(\"canvas\");\n        c.width = c.height = 512;\n        const x = c.getContext(\"2d\");\n        const g = x.createLinearGradient(0, 0, 512, 512);\n        g.addColorStop(0, \"#ddd9d0\");\n        g.addColorStop(.55, \"#aaa49a\");\n        g.addColorStop(1, \"#777168\");\n        x.fillStyle = g;\n        x.fillRect(0, 0, 512, 512);\n        for (let i = 0; i < 2800; i++) {\n          const v = 80 + Math.random() * 140;\n          x.fillStyle = `rgba(${v},${v},${v},${.03 + Math.random() * .08})`;\n          x.beginPath();\n          x.arc(Math.random() * 512, Math.random() * 512, Math.random() * 2.1 + .35, 0, Math.PI * 2);\n          x.fill();\n        }\n        return new THREE.CanvasTexture(c);\n      }\n      const stone = new THREE.MeshStandardMaterial({ color: 0xb8b3aa, map: texture(), roughness: .96 });\n      const group = new THREE.Group();\n      const slab = new THREE.Mesh(new THREE.BoxGeometry(2.3, .56, 2.3, 10, 3, 10), stone);\n      slab.castShadow = true;\n      slab.receiveShadow = true;\n      group.add(slab);\n      const reliefMat = new THREE.MeshStandardMaterial({ color: 0xd8c17d, roughness: .8 });\n      const relief = new THREE.Mesh(new THREE.BoxGeometry(1, .12, 1), reliefMat);\n      relief.position.y = .36;\n      relief.castShadow = true;\n      group.add(relief);\n      group.rotation.set(.1, -.48, -.1);\n      group.position.y = .18;\n      scene.add(group);\n\n      function resize() {\n        const rect = sceneCanvas.getBoundingClientRect();\n        renderer.setSize(rect.width, rect.height, false);\n        camera.aspect = rect.width / rect.height;\n        camera.updateProjectionMatrix();\n      }\n      addEventListener(\"resize\", resize);\n      resize();\n      let t = 0;\n      function animate() {\n        t += .012;\n        group.rotation.x = .1 + Math.sin(t) * .025;\n        group.rotation.y = -.48 + Math.sin(t * .7) * .08;\n        renderer.render(scene, camera);\n        requestAnimationFrame(animate);\n      }\n      animate();\n    }\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/health") {
      return new Response("ok", { headers: { "content-type": "text/plain;charset=utf-8" } });
    }
    return new Response(HTML, {
      headers: {
        "content-type": "text/html;charset=utf-8",
        "cache-control": "public, max-age=60"
      }
    });
  }
};
